<main id="main" class="page auth-page"><div class="auth-intro"><span class="auth-emblem"><?= icon('ball') ?></span><h1>Um lugar para<br><span>o seu time.</span></h1><p>Guarde sua combinação favorita e encontre seus parceiros quando voltar.</p><div class="auth-pokemon-art"><img src="<?= e(img('stat/stat-pikachu.png')) ?>" alt="Pikachu"><img src="<?= e(img('stat/stat-umbreon.png')) ?>" alt="Umbreon"></div></div>
<section class="auth-form-panel" aria-labelledby="auth-title"><h2 id="auth-title"><?= $mode === 'register' ? 'Seu laboratório começa aqui.' : 'Bom ter você de volta.' ?></h2><p><?= $mode === 'register' ? 'Crie seu perfil de treinador para salvar sua equipe.' : 'Entre para continuar montando sua equipe.' ?></p>
<?php if ($error): ?><div class="form-error" role="alert"><?= e($error) ?></div><?php endif ?>
<form method="post" action="<?= e(route($mode)) ?>" class="auth-form"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>">
<?php if ($mode === 'register'): ?><label for="name">Nome de treinador</label><input id="name" name="name" autocomplete="nickname" required minlength="2" maxlength="40" value="<?= e($values['name']) ?>" placeholder="Como vamos chamar você?"><?php endif ?>
<label for="email">E-mail</label><input id="email" name="email" type="email" autocomplete="email" required maxlength="254" value="<?= e($values['email']) ?>" placeholder="voce@exemplo.com">
<label for="password">Senha</label><div class="password-field"><input id="password" name="password" type="password" autocomplete="<?= $mode === 'register' ? 'new-password' : 'current-password' ?>" required minlength="8" maxlength="72" aria-describedby="password-hint"><button type="button" id="show-password" aria-controls="password" aria-pressed="false">Mostrar</button></div><small id="password-hint"><?= $mode === 'register' ? 'Use pelo menos 8 caracteres. Não precisa ser a senha de outro serviço.' : 'Informe a senha da sua conta PokéLab.' ?></small>
<?php if ($mode === 'login'): ?><a class="forgot-link" href="<?= e(route('forgot')) ?>">Esqueci minha senha</a><?php endif ?>
<button class="button button-dark auth-submit"><?= $mode === 'register' ? 'Criar minha conta' : 'Entrar no laboratório' ?> <?= icon('arrow') ?></button></form>
<p class="auth-alternate"><?= $mode === 'register' ? 'Já tem uma conta?' : 'Primeira visita?' ?> <a href="<?= e(route($mode === 'register' ? 'login' : 'register')) ?>"><?= $mode === 'register' ? 'Entrar' : 'Criar conta' ?></a></p><a class="text-link" href="<?= e(route('team')) ?>">Continuar como visitante</a></section></main>
